1	'use client'
2	
3	import dynamic from 'next/dynamic'
4	import { useCallback } from 'react'
5	import { useRouter, useSearchParams } from 'next/navigation'
6	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
7	import { toast } from 'sonner'
8	import { Skeleton } from '@/components/ui/skeleton'
9	import { AppointmentDrawer } from '@/components/appointments/AppointmentDrawer'
10	import type { CalendarBooking } from '@/components/calendar/CalendarView'
11	import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'
12	import { PageShell } from '@/components/shared/PageShell'
13	
14	// Must be ssr:false — FullCalendar uses browser globals
15	const CalendarView = dynamic(
16	  () =>
17	    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
18	  {
19	    ssr: false,
20	    loading: () => (
21	      <div className="flex-1 p-4 space-y-3">
22	        <div className="flex items-center gap-3">
23	          <Skeleton className="h-9 w-32 rounded-lg" />
24	          <Skeleton className="h-9 w-24 rounded-lg" />
25	          <Skeleton className="h-9 w-24 rounded-lg" />
26	          <div className="ml-auto flex gap-2">
27	            <Skeleton className="h-9 w-9 rounded-lg" />
28	            <Skeleton className="h-9 w-20 rounded-lg" />
29	            <Skeleton className="h-9 w-9 rounded-lg" />
30	          </div>
31	        </div>
32	        <Skeleton className="h-[60vh] w-full rounded-xl" />
33	      </div>
34	    ),
35	  }
36	)
37	
38	// ── C7: URL search param helpers ────────────────────────────────────────────
39	function parseIds(value: string | null): string[] {
40	  if (!value) return []
41	  return value.split(',').filter(Boolean)
42	}
43	
44	function serializeIds(ids: string[]): string {
45	  return ids.join(',')
46	}
47	
48	export function CalendarPageClient() {
49	  const router = useRouter()
50	  const searchParams = useSearchParams()
51	  const queryClient = useQueryClient()
52	
53	  // ── C7: Lift filter state into URL ─────────────────────────────────────
54	  const filterArtistIds = parseIds(searchParams.get('artists'))
55	  const filterStatuses = parseIds(searchParams.get('statuses'))
56	  const filterServiceIds = parseIds(searchParams.get('services'))
57	
58	  function updateFilters(updates: {
59	    artists?: string[]
60	    statuses?: string[]
61	    services?: string[]
62	  }) {
63	    const next = new URLSearchParams(searchParams.toString())
64	    if (updates.artists !== undefined) {
65	      if (updates.artists.length > 0) {
66	        next.set('artists', serializeIds(updates.artists))
67	      } else {
68	        next.delete('artists')
69	      }
70	    }
71	    if (updates.statuses !== undefined) {
72	      if (updates.statuses.length > 0) {
73	        next.set('statuses', serializeIds(updates.statuses))
74	      } else {
75	        next.delete('statuses')
76	      }
77	    }
78	    if (updates.services !== undefined) {
79	      if (updates.services.length > 0) {
80	        next.set('services', serializeIds(updates.services))
81	      } else {
82	        next.delete('services')
83	      }
84	    }
85	    router.replace(`?${next.toString()}`, { scroll: false })
86	  }
87	
88	  // ── Drawer state ────────────────────────────────────────────────────────
89	  const {
90	    drawerOpen,
91	    setDrawerOpen,
92	    editingId,
93	    defaultStart,
94	    defaultEnd,
95	    openNew,
96	    openEdit,
97	  } = useCalendarDrawer()
98	
99	  const {
100	    data,
101	    isLoading,
102	    error,
103	    refetch,
104	  } = useQuery<{ data: CalendarBooking[]; count: number }>({
105	    queryKey: ['bookings', 'calendar'],
106	    queryFn: async () => {
107	      const res = await fetch('/api/bookings?per_page=500')
108	      if (!res.ok) throw new Error('Failed to fetch bookings')
109	      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
110	    },
111	  })
112	
113	  const rescheduleMutation = useMutation({
114	    mutationFn: async ({
115	      id,
116	      newStart,
117	      newEnd,
118	    }: {
119	      id: string
120	      newStart: Date
121	      newEnd: Date
122	    }) => {
123	      const durationMs = newEnd.getTime() - newStart.getTime()
124	      const duration_min = Math.round(durationMs / 60000)
125	      const res = await fetch(`/api/bookings/${id}`, {
126	        method: 'PATCH',
127	        headers: { 'Content-Type': 'application/json' },
128	        body: JSON.stringify({
129	          scheduled_at: newStart.toISOString(),
130	          duration_min,
131	        }),
132	      })
133	      if (!res.ok) {
134	        const err = await res.json() as { error?: string }
135	        throw new Error(err.error ?? 'Reschedule failed')
136	      }
137	      return res.json()
138	    },
139	    onSuccess: () => {
140	      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
141	    },
142	  })
143	
144	  const handleReschedule = useCallback(
145	    async (id: string, newStart: Date, newEnd: Date) => {
146	      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
147	    },
148	    [rescheduleMutation]
149	  )
150	
151	  const bookings = data?.data ?? []
152	  const totalBookings = data?.count ?? 0
153	
154	  return (
155	    <PageShell fullHeight>
156	      <CalendarView
157	        bookings={bookings}
158	        isLoading={isLoading}
159	        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
160	        totalBookings={totalBookings}
161	        filterArtistIds={filterArtistIds}
162	        filterStatuses={filterStatuses}
163	        filterServiceIds={filterServiceIds}
164	        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
165	        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
166	        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
167	        onNewAppointment={openNew}
168	        onEditAppointment={openEdit}
169	        onReschedule={handleReschedule}
170	        onRetry={() => {
171	          void refetch()
172	        }}
173	      />
174	
175	      <AppointmentDrawer
176	        open={drawerOpen}
177	        onOpenChange={setDrawerOpen}
178	        editingId={editingId}
179	        {...(defaultStart !== undefined ? { defaultStart } : {})}
180	        {...(defaultEnd !== undefined ? { defaultEnd } : {})}
181	        onSuccess={() => {
182	          setDrawerOpen(false)
183	          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
184	          toast.success(editingId ? 'Appointment updated' : 'Appointment created')
185	        }}
186	      />
187	    </PageShell>
188	  )
189	}
